const item = $input.first();
const body = item.json.body || item.json;
const binary = item.binary || {};
const keys = Object.keys(binary);
if (!keys.length) throw new Error('Nenhum arquivo enviado. Use o campo "video" no formulário.');
const file = binary[keys[0]];
const fileName = String(body.original_filename || file.fileName || 'input');
const match = fileName.match(/.[a-z0-9]+$/i);
const extension = match ? match[0].toLowerCase() : '.mp4';
const jobId = String($execution.id);
return {
  json: {
    ...body,
    job_id: jobId,
    source_name: fileName,
    source_ext: extension,
    source_mime: String(file.mimeType || 'application/octet-stream'),
    source_size: file.fileSize || null,
    job_started_at: new Date().toISOString(),
  },
  binary: { data: file },
};

const transcript = $input.first().json || {};
const form = $('Iniciar Job').first().json || {};
const jobId = String(form.job_id || $execution.id);
function parseList(value) {
  if (Array.isArray(value)) return value;
  try {
    const parsed = JSON.parse(value || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    return [];
  }
}
const lyricsText = String(form.official_lyrics || '');
let hash = 0;
for (let index = 0; index < lyricsText.length; index += 1) {
  hash = ((hash << 5) - hash + lyricsText.charCodeAt(index)) | 0;
}
const fingerprint = 'lyr_' + Math.abs(hash).toString(36);
const duration = Number(transcript.duration || transcript.metadata?.duration || 0);
const extension = String(form.source_ext || '.mp4').toLowerCase();
const mimeMap = {
  '.mp4': 'video/mp4',
  '.mov': 'video/quicktime',
  '.webm': 'video/webm',
  '.m4v': 'video/x-m4v',
  '.mkv': 'video/x-matroska',
  '.mp3': 'audio/mpeg',
  '.wav': 'audio/wav',
  '.m4a': 'audio/mp4',
  '.aac': 'audio/aac',
  '.ogg': 'audio/ogg',
  '.flac': 'audio/flac',
  '.opus': 'audio/opus',
};
const declaredMime = String(form.source_mime || '').toLowerCase();
const sourceMime =
  declaredMime && declaredMime !== 'application/octet-stream'
    ? declaredMime
    : mimeMap[extension] || 'application/octet-stream';
const job = {
  version: 1,
  jobId,
  status: 'awaiting_sync',
  created_at: form.job_started_at || new Date().toISOString(),
  updated_at: new Date().toISOString(),
  source: {
    key: 'jobs/' + jobId + '/source' + extension,
    filename: form.source_name || 'input',
    mime: sourceMime,
    duration,
    size: form.source_size || null,
  },
  lyrics: {
    text: lyricsText,
    language: form.language || 'pt',
    segmentation_mode: form.segmentation_mode || 'lyrics',
    pause_threshold: Number(form.pause_threshold || 1.5),
    fingerprint,
  },
  settings: {
    templates: parseList(form.templates),
    background_mode: form.background_mode || 'none',
    background_keys: parseList(form.background_keys),
    output_aspect: form.output_aspect || '9:16',
    output_quality: form.output_quality || '1080',
    fill_mode: form.fill_mode || 'contain',
  },
  draft: {
    engine: 'whisperx-whole',
    words: Array.isArray(transcript.words) ? transcript.words : [],
    lines: Array.isArray(transcript.lines) ? transcript.lines : [],
    peaks: Array.isArray(transcript.peaks) ? transcript.peaks : [],
    duration,
    warnings: transcript.metadata?.warnings || [],
    low_confidence_words: transcript.metadata?.low_confidence_words || 0,
    interpolated_words: transcript.metadata?.interpolated_words || 0,
  },
  timeline: null,
};
const payload = JSON.stringify(job, null, 2);
return {
  json: job,
  binary: { data: {
    data: Buffer.from(payload, 'utf8').toString('base64'),
    mimeType: 'application/json',
    fileName: 'job.json',
  } },
};

